using ATLink.Core;
using System.Data;
using System.Text.Json;
internal static class CompetitionParityChecks
{
    public static void Run(string root)
    {
        void Check(bool ok,string message){if(!ok)throw new Exception(message);}
        void Reject(Action action,string message){try{action();throw new Exception(message);}catch(InvalidDataException){}}
        string dir=Path.Combine(root,"files/FC27"),meta=Path.Combine(dir,"fifa_ng_db-meta.xml"),locmeta=Path.Combine(dir,"eng_us-meta.xml");
        var c=new CompetitionProjectContext(CompdataProject.Open(Path.Combine(dir,"compdata")),"FC27",DatabaseDocument.Open(Path.Combine(dir,"fifa_ng_db.db"),meta),DatabaseDocument.Open(Path.Combine(dir,"eng_us.db"),locmeta),meta,locmeta);
        var originals=c.Project.Files.ToDictionary(f=>f.RelativePath,f=>f.Text);
        foreach(var obj in c.Objects.Where(o=>o.Kind==3)){_=FootballSeason.Read(c,obj.Id);_=FootballBehaviour.ReadLinks(c,obj.Id);}
        Check(!c.HasChanges&&c.Project.Files.All(f=>f.Text==originals[f.RelativePath]),"Reading season behaviour changed native data");
        int nativeLeague=c.Objects.Single(o=>o.Code=="C13").Id,nativeCup=c.Objects.Single(o=>o.Code=="C201").Id;
        var teams=c.Teams.Take(32).Select(t=>t.Id).ToArray();var league=new FootballPhase{Name="League",Kind=FootballPhaseKind.League,Participants=8,Groups=1,Legs=2};
        var cup=new FootballPhase{Name="Cup",Kind=FootballPhaseKind.Knockout,Participants=16,Rounds=4,Legs=1,FinalLegs=1};
        var calendar=new FootballCalendarPlan(FootballCalendarMode.Generate,new DateOnly(2027,12,29),3,"19:45");
        FootballBehaviourPlan Plan(FootballSeasonTask[]? tasks=null,FootballStandingSeed[]? seeds=null,bool automatic=true,FootballCalendarPlan? dates=null)=>new(tasks??[],seeds??[],automatic,new(),dates??calendar);
        int Create(FootballCompetitionKind kind,FootballPhase[] phases,string[] clubs,FootballBehaviourPlan? behaviour=null)
        {int id=0;c.Execute("Parity create",()=>id=FootballCompetitionCompiler.Create(c,kind,507,"Parity "+kind,phases,clubs,new Dictionary<string,string[]>(),behaviour));Check(CompetitionEditing.Validate(c.Project).Count==0,"Native structure validation");return id;}
        int leagueId=Create(FootballCompetitionKind.League,[league],teams[..8],Plan());var leagueModel=FootballCompetitionAdapter.Read(c,leagueId);int leagueDb=FootballSeason.DatabaseId(c,leagueId);
        var leagueTasks=FootballSeason.Read(c,leagueId).Tasks;Check(leagueTasks.Count(t=>t.Action=="UpdateTable")==8,"League final table update missing");Check(leagueTasks.Any(t=>t.Action=="ClearLeagueStats"&&t.Parameters[0]==leagueDb)&&leagueTasks.Any(t=>t.Action=="UpdateLeagueStats"&&t.Parameters[0]==leagueDb),"New league statistics reference incorrect");
        int allocation=FootballQualifications.EntryPools(c,leagueId).Single();int leaguePhase=leagueModel.Phases.Single().NativeId!.Value,leagueGroup=leagueModel.Phases.Single().NativeGroups.Single();
        int nation=int.Parse(FootballCatalog.Value(c.Base!.Tables.Single(t=>t.Name=="nations").Data.Rows.Cast<DataRow>().First(r=>int.Parse(FootballCatalog.Value(r,"nationid"))>0),"nationid"));
        foreach(var action in FootballSeason.Actions)
        {
            int[] parameters=action.Code switch{"FillWithTeam"=>[1,int.Parse(teams[0])],"FillFromLeague" or "FillFromLeagueInOrder"=>[13],"FillFromSpecialTeams"=>[2],"FillFromSpecialTeamsWithNation"=>[2,nation],"FillFromLeagueMaxFromCountry"=>[13,2,1],"FillFromTopCoefficientCountry"=>[1,2,1],"FillFromCompTable"=>[nativeLeague,2],"FillFromCompTableBackupLeague"=>[nativeLeague,13,2],"FillFromCompTableBackup"=>[nativeLeague,nativeCup,2],"UpdateTable"=>[leagueGroup,1,1],_=>[leagueDb]};
            var typed=new FootballSeasonTask(action.Code,new(action.TargetKind==5?allocation:action.TargetKind==4?leaguePhase:leagueId),parameters);var native=FootballSeason.Native(c,leagueId,typed);
            Check(native.Length==7&&native[1]==(action.End?"end":"start")&&native[2]==action.Code&&native.Skip(4).Select(int.Parse).Take(parameters.Length).SequenceEqual(parameters),"DBM task serialization differs: "+action.Code);
        }
        var leagueSlots=c.Calendar(leagueId).Where(s=>s.FixedDate is null&&!FootballCompetitionAdapter.IsHidden(c,s.ObjectId)).ToArray();Check(leagueSlots.Length==14&&leagueSlots.All(s=>s.Time=="1945")&&leagueSlots[1].Date(c.ReferenceDate)==new DateOnly(2028,1,1),"Configurable cross-year calendar");
        var resized=leagueModel.Phases.Select(p=>p with{Participants=10}).ToArray();var resizePreview=FootballCompetitionCompiler.Preview(c,leagueId,resized);c.Execute("Resize managed entry pool",()=>FootballCompetitionCompiler.Compile(c,leagueId,resizePreview,true));
        Check(FootballQualifications.EntryPools(c,leagueId).All(g=>c.Rows("standings.txt").Count(r=>r[0]==g.ToString())==10),"Known setup pool did not resize with the played phase");Check(FootballParticipants.Read(c,leagueId).Count==10&&FootballParticipants.Read(c,leagueId).Count(p=>p.Unassigned)==2,"New places must stay explicitly unassigned");Check(FootballSeason.Read(c,leagueId).Tasks.Count(t=>t.Action=="UpdateTable")==10,"Generated final-results map did not resize");c.Undo();
        var addFinal=new[]{leagueModel.Phases[0] with{QualifiersPerGroup=2},new FootballPhase{Name="Final",Kind=FootballPhaseKind.Knockout,Participants=2,Rounds=1,Legs=1,FinalLegs=1}};var finalPreview=FootballCompetitionCompiler.Preview(c,leagueId,addFinal);c.Execute("Add managed final",()=>FootballCompetitionCompiler.Compile(c,leagueId,finalPreview,true));var movedFinal=FootballCompetitionAdapter.Read(c,leagueId).Phases.Last().NativeGroups.Single();Check(FootballSeason.Read(c,leagueId).Tasks.Count(t=>t.Action=="UpdateTable"&&t.Parameters[0]==movedFinal)==2,"Final-results source did not follow the new final");Check(c.Rows("settings.txt").Any(r=>r[0]==movedFinal.ToString()&&r[1]=="info_slot_champ"&&r[2]=="1"),"Champion marker did not follow the new final");c.Undo();
        int cupId=Create(FootballCompetitionKind.Cup,[cup],teams[..16],Plan());var cupModel=FootballCompetitionAdapter.Read(c,cupId);
        for(int i=0;i<cupModel.Phases[1].NativeGroups.Count;i++)
        {
            var routes=c.Rows("advancement.txt").Where(r=>r[2]==cupModel.Phases[1].NativeGroups[i].ToString()).OrderBy(r=>int.Parse(r[3])).ToArray();
            Check(routes.Length==2&&int.Parse(routes[0][0])==cupModel.Phases[0].NativeGroups[2*i]&&int.Parse(routes[1][0])==cupModel.Phases[0].NativeGroups[2*i+1],"DBM adjacent knockout pairing differs");
        }
        Check(FootballSeason.Read(c,cupId).Tasks.Count(t=>t.Action=="UpdateTable")==2,"Final winner/runner-up season results missing");
        Check(c.Objects.Any(o=>o.ParentId==cupId&&o.Code=="S1"&&FootballCompetitionAdapter.IsHidden(c,o.Id))&&c.Objects.Single(o=>o.Id==cupModel.Phases[0].NativeId).Code=="S2","Native setup/played stage codes");
        var group=new FootballPhase{Name="Groups",Kind=FootballPhaseKind.Groups,Participants=16,Groups=4,QualifiersPerGroup=2,Legs=2};
        int grouped=Create(FootballCompetitionKind.GroupsAndKnockout,[group,cup with{Participants=8,Rounds=3,Legs=2,FinalLegs=1}],teams[..16],Plan());var groupedModel=FootballCompetitionAdapter.Read(c,grouped);Check(groupedModel.Phases.Last().Legs==1&&groupedModel.Phases.Skip(1).First().Legs==2,"Two-leg rounds and single final");
        int mixed=Create(FootballCompetitionKind.Custom,[new(){Name="Qualifying",Kind=FootballPhaseKind.Knockout,Participants=32,Rounds=1,Legs=2},group,cup with{Participants=8,Rounds=3}],teams,Plan());Check(FootballCompetitionAdapter.Read(c,mixed).Phases.Count==5,"Mixed sporting flow");
        var dynamic=new FootballSeasonTask("FillFromCompTableBackupLeague",new(0),[nativeLeague,13,8]);var seeds=teams[..8].Select((id,i)=>new FootballStandingSeed(id,i)).ToArray();int dynamicId=Create(FootballCompetitionKind.Cup,[cup with{Participants=8,Rounds=3}],[],Plan([dynamic],seeds));
        var imported=FootballSeason.Read(c,dynamicId);var dynamicTask=imported.Tasks.Single(t=>t.Action==dynamic.Action);Check(dynamicTask.Parameters.SequenceEqual(dynamic.Parameters)&&c.Rows("tasks.txt").Any(r=>r[0]==dynamicId.ToString()&&r[2]==dynamic.Action)&&!imported.Tasks.Any(t=>t.Action=="FillWithTeam"),"Dynamic rule was expanded to today's clubs");Check(c.Rows("initteams.txt").Count(r=>r[0]==dynamicId.ToString())==8,"Explicit zero-based initial standings missing");
        int partial=Create(FootballCompetitionKind.Cup,[cup with{Participants=8,Rounds=3}],teams[..4],Plan([dynamic with{Parameters=[nativeLeague,13,4]}]));Check(FootballSeason.Read(c,partial).Tasks.Count(t=>t.Action=="FillWithTeam")==4,"Mixed named and dynamic entries");
        var fixtures=calendar with{Mode=FootballCalendarMode.AssignedFixtures,FirstDate=new DateOnly(2028,2,27),IntervalDays=2};int fixtureId=Create(FootballCompetitionKind.League,[league with{Participants=4}],teams[..4],Plan(dates:fixtures));Check(c.Calendar(fixtureId).Count(s=>s.FixedDate.HasValue)==12&&c.Calendar(fixtureId).Any(s=>s.FixedDate==new DateOnly(2028,2,29)),"Assigned fixtures and leap day");
        c.Execute("Manual assigned match",()=>FootballBehaviour.AddAssignedFixture(c,fixtureId,FootballCompetitionAdapter.Read(c,fixtureId).Phases[0].NativeId!.Value,new DateOnly(2028,4,1),"18:15",teams[0],teams[1]));Check(c.Calendar(fixtureId).Count(s=>s.FixedDate.HasValue)==13,"Manual assigned match missing");
        Reject(()=>c.Execute("Clashing assigned match",()=>FootballBehaviour.AddAssignedFixture(c,fixtureId,FootballCompetitionAdapter.Read(c,fixtureId).Phases[0].NativeId!.Value,new DateOnly(2028,4,1),"18:15",teams[0],teams[2])),"Assigned match double booking accepted");c.Undo();
        Reject(()=>c.Execute("Bad source count",()=>FootballCompetitionCompiler.Create(c,FootballCompetitionKind.Cup,507,"Invalid",[cup with{Participants=8,Rounds=3}],[],new Dictionary<string,string[]>(),Plan([dynamic with{Parameters=[nativeLeague,13,7]}]))),"Inconsistent dynamic entry count accepted");
        Reject(()=>FootballSeason.Validate(c,dynamicId,dynamicTask with{Parameters=[13,13,8]}),"DB league ID mistaken for Compdata competition object ID");
        Reject(()=>FootballSeason.Validate(c,dynamicId,new("UpdateTable",new(dynamicId),[FootballCompetitionAdapter.Read(c,dynamicId).Phases.Last().NativeGroups[0],3,1])),"Invalid finishing place accepted");
        c.Execute("Unknown native marker",()=>{c.Edit("tasks.txt",t=>t.Data.Rows.Add(dynamicId.ToString(),"start","UnrecognizedGameAction",dynamicTask.Target.Value.ToString(),"9","0","0"));c.SetRule(dynamicId,"unrecognized_setting",["keep-me"]);});
        var snapshot=FootballSeason.Read(c,dynamicId);string marker=c.Rows("tasks.txt").Single(r=>r[0]==dynamicId.ToString()&&r[2]=="UnrecognizedGameAction").Aggregate((a,b)=>a+","+b);var before=c.Project.Files.ToDictionary(f=>f.RelativePath,f=>f.Text);
        c.Execute("No-op native task save",()=>FootballSeason.ApplyTasks(c,dynamicId,snapshot,snapshot.Tasks));Check(c.Project.Files.All(f=>before[f.RelativePath]==f.Text),"No-op season save rewrote source data");c.Undo();
        snapshot=FootballSeason.Read(c,dynamicId);var changed=snapshot.Tasks.Select(t=>t.Action==dynamic.Action?t with{Parameters=[nativeLeague,13,6]}:t).ToArray();c.Execute("Edit dynamic count",()=>FootballSeason.ApplyTasks(c,dynamicId,snapshot,changed));Check(FootballSeason.Read(c,dynamicId).Tasks.Any(t=>t.Action==dynamic.Action&&t.Parameters[2]==6),"Dynamic count edit");Check(c.Rows("tasks.txt").Any(r=>string.Join(',',r)==marker),"Unknown task removed");c.Undo();c.Redo();c.Undo();
        snapshot=FootballSeason.Read(c,leagueId);var reordered=snapshot.Tasks.ToArray();(reordered[0],reordered[1])=(reordered[1],reordered[0]);c.Execute("Reorder tasks",()=>FootballSeason.ApplyTasks(c,leagueId,snapshot,reordered));Check(FootballSeason.Read(c,leagueId).Tasks[0].Parameters.SequenceEqual(reordered[0].Parameters),"Task order ignored");c.Undo();
        var links=new FootballSeasonLinks(new(14),null,new(nativeCup),8);c.Execute("Season links",()=>FootballSeason.ApplyLinks(c,leagueId,links));Check(c.Rows("settings.txt").Any(r=>r[0]==leagueId.ToString()&&r[1]=="info_league_promo"&&r[2]=="14")&&c.Rows("settings.txt").Any(r=>r[0]==leagueId.ToString()&&r[1]=="schedule_forcecomp"&&r[2]==nativeCup.ToString()),"Typed DB/object season links");
        int fixtureGroup=FootballCompetitionAdapter.Read(c,fixtureId).Phases[0].NativeGroups[0];c.Execute("Internal reference",()=>c.SetRule(fixtureId,"rule_suspension",[fixtureGroup.ToString()]));int duplicate=0;c.Execute("Duplicate",()=>duplicate=FootballCompetitionCompiler.Duplicate(c,fixtureId,"Parity duplicate"));
        var duplicateScope=c.Scope(duplicate);Check(c.Rows("settings.txt").Any(r=>r[0]==duplicate.ToString()&&r[1]=="rule_suspension"&&duplicateScope.Contains(int.Parse(r[2]))&&!c.Scope(fixtureId).Contains(int.Parse(r[2]))),"Duplicate internal rule reference not remapped");Check(c.Calendar(duplicate).Count(s=>s.FixedDate.HasValue)==12,"Duplicate fixtures lost");Check(FootballSeason.Read(c,duplicate).Tasks.Where(t=>t.Action is "ClearLeagueStats" or "UpdateLeagueStats").All(t=>t.Parameters[0]==FootballSeason.DatabaseId(c,duplicate)),"Duplicate updates original league statistics");
        c.Execute("Regenerate",()=>FootballBehaviour.RegenerateCalendar(c,leagueId,calendar with{IntervalDays=5,Kickoff="21:15"},true));Check(c.Calendar(leagueId).Where(s=>!FootballCompetitionAdapter.IsHidden(c,s.ObjectId)).All(s=>s.Time=="2115"),"Calendar time ignored");c.Undo();Reject(()=>c.Execute("Replace fixtures",()=>FootballBehaviour.RegenerateCalendar(c,fixtureId,calendar,true)),"Assigned fixtures overwritten");
        int emptyTarget=Create(FootballCompetitionKind.Cup,[cup with{Participants=4,Rounds=2}],[],Plan());var label=FootballQualifications.Available(c).First(k=>k.Key=="info_label_slot_uel");int pool=FootballQualifications.EntryPools(c,emptyTarget).Single();
        c.Execute("Continental link",()=>FootballQualifications.ConnectTopTeams(c,leagueId,leagueModel.Phases.Single().NativeGroups[0],2,label.Key,emptyTarget,pool));Check(FootballSeason.Read(c,emptyTarget).Tasks.Any(t=>t.Action=="FillFromCompTable"&&t.Parameters.SequenceEqual(new[]{leagueId,2})),"Continental qualification is only a visual flag");c.Undo();Check(!FootballSeason.Read(c,emptyTarget).Tasks.Any(t=>t.Action=="FillFromCompTable"),"Cross-competition qualification undo");c.Redo();
        var preciseRows=new[]{new FootballMatchdayDraft(0,1,new DateOnly(2028,2,27),"17:30",0,2),new FootballMatchdayDraft(0,2,new DateOnly(2028,2,29),"20:15",0,2),new FootballMatchdayDraft(0,3,new DateOnly(2028,3,3),"16:45",0,2)};
        var precise=calendar with{Mode=FootballCalendarMode.ManualMatchdays,Matchdays=preciseRows,Fixtures=[new(0,new DateOnly(2028,2,29),"20:15",teams[0],teams[1])]};
        int manualCalendar=Create(FootballCompetitionKind.League,[league with{Participants=4,Legs=1}],teams[..4],Plan(dates:precise));var manualEvents=c.Calendar(manualCalendar).Where(s=>!FootballCompetitionAdapter.IsHidden(c,s.ObjectId)).ToArray();
        Check(manualEvents.Count(s=>!s.FixedDate.HasValue)==3&&manualEvents.Any(s=>!s.FixedDate.HasValue&&s.Date(c.ReferenceDate)==new DateOnly(2028,2,29)&&s.Time=="2015"),"Precise matchday dates were regenerated or shifted");Check(manualEvents.Any(s=>s.FixedDate==new DateOnly(2028,2,29)&&s.Home==teams[0]&&s.Away==teams[1]),"Known fixture was not added alongside matchday slots");
        var specs=FootballExactCalendar.Phases([league with{Participants=4,Legs=1}]);Reject(()=>FootballExactCalendar.Validate(c,specs,precise with{Matchdays=preciseRows.Take(1).ToArray()}),"Missing matchday dates accepted");Reject(()=>FootballExactCalendar.Validate(c,specs,precise with{Matchdays=preciseRows.Append(preciseRows[0]).ToArray()}),"Duplicate matchday time slot accepted");Reject(()=>FootballExactCalendar.Validate(c,specs,precise with{Fixtures=[new(0,new DateOnly(2028,3,1),"20:15",teams[0],teams[1])]}),"Fixture outside its matchday slots accepted");
        Reject(()=>FootballExactCalendar.Validate(c,specs,precise with{Matchdays=preciseRows.Select((r,i)=>i==0?r with{Kickoff="25:10"}:r).ToArray()}),"Invalid manual kick-off accepted");
        var split=precise with{Fixtures=[],Matchdays=new[]{preciseRows[0] with{Maximum=1},preciseRows[0] with{Kickoff="20:00",Maximum=1},preciseRows[1],preciseRows[2]}};FootballExactCalendar.Validate(c,specs,split);
        var exact=calendar with{Mode=FootballCalendarMode.ExactFixtures,Fixtures=[new(3,new DateOnly(2028,7,1),"21:35",teams[0],teams[1])]};int exactCup=Create(FootballCompetitionKind.Cup,[cup],teams[..16],Plan(dates:exact));Check(!c.Calendar(exactCup).Any(s=>!s.FixedDate.HasValue)&&c.Calendar(exactCup).Any(s=>s.FixedDate==new DateOnly(2028,7,1)&&s.Time=="2135"),"Exact fixtures were mixed with an unwanted automatic calendar");Check(c.Project.Files.Any(f=>Path.GetFileName(f.RelativePath)==c.Objects.Single(o=>o.Id==exactCup).Code.ToLowerInvariant()+"_s5_2028.txt"),"Fixture phase mapping did not reach the final");
        Reject(()=>FootballExactCalendar.Validate(c,FootballExactCalendar.Phases([cup]),exact with{Fixtures=[new(0,new DateOnly(2028,7,1),"21:35",teams[0],teams[1]),new(1,new DateOnly(2028,7,1),"21:35",teams[0],teams[2])]}),"Same club double-booked in two phases");
        var twoLegSpecs=FootballExactCalendar.Phases([cup with{Participants=8,Rounds=3,Legs=2,FinalLegs=1}]);Check(twoLegSpecs.Select(p=>p.Rounds).SequenceEqual(new[]{2,2,1}),"Calendar lost the separate final leg count");
        string output=Path.Combine(root,"Checks/output/parity-"+Guid.NewGuid().ToString("N"));
        try{c.Export(output);var reopened=c.OpenProject(output);Check(reopened.CompetitionMappings.Count==c.CompetitionMappings.Count,"Project identity mappings lost on reopen");using(var manifest=JsonDocument.Parse(File.ReadAllText(Path.Combine(output,"project.json"))))Check(manifest.RootElement.GetProperty("ValidationLevels").GetProperty("InGame").GetString()=="Not performed","Export claims in-game validation");Check(FootballSeason.Read(reopened,dynamicId).Tasks.Any(t=>t.Action==dynamic.Action)&&reopened.Rows("settings.txt").Any(r=>r[1]=="unrecognized_setting"&&r[2]=="keep-me"),"Export/reopen season and unknown settings");Check(reopened.Calendar(fixtureId).Any(s=>s.FixedDate==new DateOnly(2028,2,29)),"Exported leap-day fixture");Check(reopened.Calendar(manualCalendar).Count(s=>!s.FixedDate.HasValue)==3&&reopened.Calendar(exactCup).Any(s=>s.FixedDate==new DateOnly(2028,7,1)&&s.Time=="2135"),"Precise creation calendar lost on export/reopen");}
        finally{if(Directory.Exists(output))Directory.Delete(output,true);}
        foreach(var original in originals)Check(File.ReadAllText(Path.Combine(dir,"compdata",original.Key))==original.Value,"Source FC27 file changed");Check(!c.Base!.HasChanges&&!c.Localization!.HasChanges,"Source DB/LOC mutated");
        Console.WriteLine("PASS competition parity: DBM adjacent knockout paths; FC27 result/statistics profiles; all typed source/operation references; dynamic and mixed entries; initial standings; configurable/assigned/leap calendars; unknown preservation; ordered tasks; promotion/playoff IDs; duplication remapping; continental entry links; history; integrated export/reopen. In-game validation NOT performed.");
    }
}